export function traduire(phrase, langue = langueCourante) {
  return TEXTES[langue]?.[phrase] || phrase;
}

export function localePourLangue(langue = langueCourante) {
  return { fr: "fr-FR", en: "en-GB", es: "es-ES", pt: "pt-PT", ar: "ar" }[langue] || "fr-FR";
}

export function TexteLocalise({ phrase }) {
  const { langue } = useLangue();
  return traduire(phrase, langue);
}

function preferenceInitiale(cle, valeurDefaut, valeursAutorisees) {
  try {
    const valeur = window.localStorage.getItem(cle);
    return valeursAutorisees.includes(valeur) ? valeur : valeurDefaut;
  } catch {
    return valeurDefaut;
  }
}

export function LangueProvider({ children }) {
  const [langue, setLangueValeur] = useState(() => {
    const valeur = preferenceInitiale(CLE_LANGUE, "fr", LANGUES_INTERFACE.map((item) => item.code));
    langueCourante = valeur;
    return valeur;
  });
  const [densite, setDensite] = useState(() => preferenceInitiale(CLE_DENSITE, "confortable", ["confortable", "compacte"]));
  const setLangue = (valeur) => {
    langueCourante = valeur;
    setLangueValeur(valeur);
  };

  useEffect(() => {
    const choix = LANGUES_INTERFACE.find((item) => item.code === langue) || LANGUES_INTERFACE[0];
    document.documentElement.lang = choix.code;
    document.documentElement.dir = choix.direction;
    document.documentElement.dataset.density = densite;
    try {
      window.localStorage.setItem(CLE_LANGUE, langue);
      window.localStorage.setItem(CLE_DENSITE, densite);
    } catch {
      // Les préférences restent utilisables en mémoire si le stockage navigateur est bloqué.
    }
  }, [langue, densite]);

  const valeur = useMemo(() => ({ langue, setLangue, densite, setDensite }), [langue, densite]);
  return <CONTEXTE.Provider value={valeur}>{children}</CONTEXTE.Provider>;
}

export function useLangue() {
  const valeur = useContext(CONTEXTE);
  if (!valeur) throw new Error("useLangue doit être utilisé dans LangueProvider.");
  return valeur;
}

export function SelecteurLangue({ compact = false }) {
  const { langue, setLangue } = useLangue();
  return <label className={`language-select ${compact ? "language-select-compact" : ""}`}>
    <span className="sr-only">{<TexteLocalise phrase={"Langue de l’interface"} />}</span>
    <select value={langue} onChange={(event) => setLangue(event.target.value)} aria-label={traduire("Choisir la langue de l’interface")}>
      {LANGUES_INTERFACE.map((item) => <option key={item.code} value={item.code}>{item.nomLocal}</option>)}
    </select>
  </label>;
}
